## Baserom data-region extracts: claim understood ROM data spans without embedding
## copyrighted bytes in source. Offsets and lengths live here; content is read from
## the local gitignored gold ROM at build/check time only.
##
## Kinds:
## - gfx_lz streams whose compressed length is well-defined (terminate at 0xFF)
## - APU package stream fragments whose container layout matches docs/audio.md
##
## Never commit the extracted bytes. See AGENTS.md copyright hygiene.
## Claims regenerated by full-gap gfx_lz scan (conductor 2026-07-24).

import
  std/[os, strformat],
  ./common

const
  ## Default gold baserom path (gitignored; user-supplied).
  GoldBaseromPath* = "bin/Earthbound (U) [!].smc"
  ## Env override for alternate local gold layouts.
  GoldBaseromEnvVar* = "DECOMPBOUND_ROM"

type
  ## Why this span is claimed as implemented data (format understanding).
  ExtractKind* = enum
    ekGfxLz
    ekApuPackage

  ## Metadata-only claim: offset/length/kind — no asset bytes.
  BaseromExtractSpan* = object
    name*: string
    offset*: int
    length*: int
    kind*: ExtractKind
    ## Short RE note (stream length source, pack id, etc.).
    note*: string

