proc resolveGoldBaseromPath*(): string =
  ## Prefer DECOMPBOUND_ROM, else the default gold path under bin/.
  result = getEnv(GoldBaseromEnvVar)
  if result.len == 0:
    result = GoldBaseromPath

proc goldBaseromAvailable*(): bool =
  ## True when a local gold baserom file exists.
  fileExists(resolveGoldBaseromPath())

proc readGoldBaseromBytes*(path: string = ""): seq[uint8] =
  ## Load gold ROM bytes, stripping a 512-byte copier header when present.
  let p = if path.len > 0: path else: resolveGoldBaseromPath()
  if not fileExists(p):
    raise newException(IOError, &"gold baserom missing at {p}")
  let data = readFile(p)
  var start = 0
  if data.len mod 1024 == 512:
    start = 512
  let bodyLen = data.len - start
  if bodyLen != EarthboundRomSize:
    raise newException(IOError,
      &"gold baserom size {bodyLen} != {EarthboundRomSize} (path={p})")
  result = newSeq[uint8](bodyLen)
  for i in 0..<bodyLen:
    result[i] = data[start + i].uint8

proc extractGoldSlice*(offset, length: int, path: string = ""): seq[uint8] =
  ## Return gold[offset .. offset+length). Never embeds bytes in the repo.
  doAssert offset >= 0
  doAssert length > 0
  doAssert offset + length <= EarthboundRomSize,
    &"extract span 0x{offset:06X}+{length} exceeds ROM"
  let gold = readGoldBaseromBytes(path)
  result = newSeq[uint8](length)
  for i in 0..<length:
    result[i] = gold[offset + i]

proc extractGoldSliceOrZeros*(offset, length: int): seq[uint8] =
  ## Like extractGoldSlice, but returns zero-fill when gold is absent.
  doAssert offset >= 0
  doAssert length > 0
  doAssert offset + length <= EarthboundRomSize
  if not goldBaseromAvailable():
    return newSeq[uint8](length)
  result = extractGoldSlice(offset, length)

proc allBaseromExtractSpans*(): seq[BaseromExtractSpan] =
  ## Metadata inventory of every known extract claim (no ROM I/O).
  result = KnownBaseromExtracts

proc totalBaseromExtractBytes*(): int =
  ## Sum of claimed extract lengths.
  for s in KnownBaseromExtracts:
    result += s.length

proc allBaseromExtractRegions*(): seq[
    tuple[name: string, offset: int, data: seq[uint8]]] =
  ## Regions for the ROM builder: name/offset plus gold (or zero) bytes.
  for s in KnownBaseromExtracts:
    result.add (
      name: s.name,
      offset: s.offset,
      data: extractGoldSliceOrZeros(s.offset, s.length))

proc isBaseromExtractOffset*(offset: int): bool =
  ## True when a file offset falls inside a claimed extract span.
  for s in KnownBaseromExtracts:
    if offset >= s.offset and offset < s.offset + s.length:
      return true
  result = false

proc extractKindName*(k: ExtractKind): string =
  ## Stable string for probes/docs.
  case k
  of ekGfxLz: "gfx_lz"
  of ekApuPackage: "apu_package"
